import { test, expect, type Page } from '@playwright/test';

const VERIFY_400 = JSON.stringify({ code: 400, error_code: 'otp_expired', msg: 'Token has expired or is invalid' });

async function mockAuth(page: Page) {
  await page.route('**/auth/v1/otp*', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: '{}' }));
  await page.route('**/auth/v1/verify*', (r) => r.fulfill({ status: 400, contentType: 'application/json', body: VERIFY_400 }));
}

async function loginToPhone(page: Page) {
  await page.goto('/welcome');
  await page.getByRole('button', { name: 'כבר יש לי חשבון? התחברות' }).click();
  await page.waitForURL(/\/phone/);
}

test.describe('Вход/регистрация — телефон и OTP', () => {
  test('Набор «501234567» → «50-123-4567», запрос с «+972501234567» @iphone @prod-safe (#4aa498)', async ({ page }) => {
    // 1. Перехватить otp/verify — до первого перехода.
    await mockAuth(page);

    // 2. /welcome → «התחברות» → /phone.
    await loginToPhone(page);

    // 3. Набрать номер посимвольно.
    const input = page.getByRole('textbox', { name: '50-000-0000' });
    await input.pressSequentially('501234567');
    await expect(input).toHaveValue('50-123-4567');
    const p = await page.getByText('+972', { exact: true }).boundingBox();
    const i = await input.boundingBox();
    expect(p, 'prefix box').not.toBeNull();
    expect(i, 'input box').not.toBeNull();
    expect(p!.x + p!.width, '«+972» слева от поля').toBeLessThanOrEqual(i!.x);

    // 4. «שליחת קוד» — запрос otp с номером в международном формате.
    const [otpReq] = await Promise.all([page.waitForRequest('**/auth/v1/otp*'), page.getByText('שליחת קוד').click()]);
    expect(otpReq.postDataJSON().phone).toBe('+972501234567');

    await page.waitForURL(/\/otp/);
    await expect(page.getByText('מה הקוד שקיבלת?')).toBeVisible();
  });
});
